-- Additive character data; existing accounts are onboarded on next visit.
CREATE TABLE character_presets (id TEXT PRIMARY KEY, appearance JSONB NOT NULL, equipment JSONB NOT NULL, animation TEXT NOT NULL, preview_asset TEXT NOT NULL);
CREATE TABLE character_cosmetics (id TEXT PRIMARY KEY, slot TEXT NOT NULL, asset_id TEXT NOT NULL, rarity TEXT NOT NULL DEFAULT 'COMMON', unlock_type TEXT NOT NULL, price_gold BIGINT NOT NULL DEFAULT 0, min_level INT NOT NULL DEFAULT 1, active BOOLEAN NOT NULL DEFAULT TRUE,
 CONSTRAINT cosmetic_valid CHECK (slot IN ('HEADWEAR','HAIR','UPPER','LOWER','SHOES','BELT','FACE_ACCESSORY','BACK','OUTERWEAR','NECKLACE','WRIST','HANDHELD','DYE','PATTERN') AND min_level > 0 AND price_gold >= 0 AND ((unlock_type IN ('FREE','LEVEL') AND price_gold = 0) OR (unlock_type = 'GOLD' AND price_gold > 0))));
ALTER TABLE user_inventory ADD COLUMN cosmetic_id TEXT REFERENCES character_cosmetics(id) ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE UNIQUE INDEX user_inventory_user_id_cosmetic_id_key ON user_inventory(user_id, cosmetic_id);
ALTER TABLE user_inventory DROP CONSTRAINT inventory_valid;
ALTER TABLE user_inventory ADD CONSTRAINT inventory_valid CHECK (
 num_nonnulls(equipment_id,bait_type_id,cosmetic_id) = 1 AND upgrade_level BETWEEN 0 AND 2 AND
 ((bait_type_id IS NOT NULL AND quantity >= 0) OR (bait_type_id IS NULL AND quantity = 1)) AND (cosmetic_id IS NULL OR upgrade_level = 0));
CREATE TABLE player_characters (id UUID PRIMARY KEY, user_id UUID NOT NULL UNIQUE REFERENCES users(id) ON DELETE RESTRICT ON UPDATE CASCADE, name VARCHAR(24) NOT NULL, preset_id TEXT NOT NULL REFERENCES character_presets(id) ON DELETE RESTRICT ON UPDATE CASCADE, appearance JSONB NOT NULL, version INT NOT NULL DEFAULT 1 CHECK (version > 0), created_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ(3) NOT NULL);
CREATE TABLE character_equipment (id UUID PRIMARY KEY, character_id UUID NOT NULL REFERENCES player_characters(id) ON DELETE RESTRICT ON UPDATE CASCADE, inventory_id UUID NOT NULL REFERENCES user_inventory(id) ON DELETE RESTRICT ON UPDATE CASCADE, slot TEXT NOT NULL, equipped_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(), UNIQUE(character_id,slot));
CREATE FUNCTION character_item_is_owned() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF NOT EXISTS (SELECT 1 FROM player_characters c JOIN user_inventory i ON i.user_id=c.user_id JOIN character_cosmetics d ON d.id=i.cosmetic_id WHERE c.id=NEW.character_id AND i.id=NEW.inventory_id AND i.quantity=1 AND d.slot=NEW.slot AND d.active) THEN
 RAISE EXCEPTION 'Character cosmetic must be owned, active and match its slot' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER character_equipment_ownership BEFORE INSERT OR UPDATE ON character_equipment FOR EACH ROW EXECUTE FUNCTION character_item_is_owned();
CREATE TABLE lake_presence (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE RESTRICT ON UPDATE CASCADE, location_id UUID NOT NULL REFERENCES fishing_locations(id) ON DELETE RESTRICT ON UPDATE CASCADE, lease_id UUID NOT NULL UNIQUE, sequence INT NOT NULL DEFAULT 0 CHECK (sequence >= 0), x DOUBLE PRECISION NOT NULL DEFAULT -4 CHECK(x BETWEEN -8 AND 8), z DOUBLE PRECISION NOT NULL DEFAULT 3 CHECK(z BETWEEN 1 AND 5), action TEXT NOT NULL DEFAULT 'IDLE', updated_at TIMESTAMPTZ(3) NOT NULL);
CREATE INDEX lake_presence_location_id_updated_at_idx ON lake_presence(location_id,updated_at);
